#!/usr/bin/env bash
# Hardware-forwarded opposite-node paths for RoCEnante (generated by scripts/ring_mesh/plan.py). Idempotent.
set -euo pipefail
tc qdisc show dev enP2p1s0f0np0 | grep -q clsact || tc qdisc add dev enP2p1s0f0np0 clsact
tc qdisc show dev enP2p1s0f1np1 | grep -q clsact || tc qdisc add dev enP2p1s0f1np1 clsact
tc filter show dev enP2p1s0f0np0 ingress pref 49159 | grep -q flower || tc filter add dev enP2p1s0f0np0 ingress protocol 0x88b5 pref 49159 handle 49159 flower skip_sw src_mac 30:c5:99:bf:e1:4c dst_mac 4c:bb:47:2e:5f:a6 action pedit ex munge eth type set 0x0800 pipe action pedit ex munge eth dst set 30:c5:99:bd:3c:96 pipe action mirred egress redirect dev enP2p1s0f1np1
tc -s filter show dev enP2p1s0f0np0 ingress pref 49159 | grep -q in_hw || { echo 'rule pref 49159 on enP2p1s0f0np0 is not in hardware'; exit 3; }
tc filter show dev enP2p1s0f1np1 ingress pref 49165 | grep -q flower || tc filter add dev enP2p1s0f1np1 ingress protocol 0x88b5 pref 49165 handle 49165 flower skip_sw src_mac 30:c5:99:bd:3c:96 dst_mac 4c:bb:47:2e:5f:a7 action pedit ex munge eth type set 0x0800 pipe action pedit ex munge eth dst set 30:c5:99:bf:e1:4c pipe action mirred egress redirect dev enP2p1s0f0np0
tc -s filter show dev enP2p1s0f1np1 ingress pref 49165 | grep -q in_hw || { echo 'rule pref 49165 on enP2p1s0f1np1 is not in hardware'; exit 3; }
ip route show exact 10.100.160.1/32 | grep -q . || ip route add 10.100.160.1/32 via 10.100.164.1 dev enp1s0f0np0 src 10.100.164.2
ip route show exact 10.100.167.1/32 | grep -q . || ip route add 10.100.167.1/32 via 10.100.163.1 dev enP2p1s0f1np1 src 10.100.163.2
for d in roceP2p1s0f1 rocep1s0f0; do systemctl start dsv41-mesh-marker@$d; done
sleep 2; for d in roceP2p1s0f1 rocep1s0f0; do systemctl is-active --quiet dsv41-mesh-marker@$d || { echo marker $d not active; exit 4; }; done
echo mesh-up OK
